cd /Users/myankelev/Code/random/cipher-box
_GSD_SHIM_NAME="gsd-tools.cjs"
GSD_TOOLS="$(git rev-parse --show-toplevel)/.claude/gsd-core/bin/${_GSD_SHIM_NAME}"
gsd_run() { node "$GSD_TOOLS" "$@"; }
PHASE_DIR=".planning/phases/68.2-sdk-owned-read-chain-and-resolved-folder-listings"
CONTEXT_PATH="${PHASE_DIR}/68.2-CONTEXT.md"

echo "===§13 REQUIREMENTS COVERAGE==="
PLAN_REQS=$(grep -h "requirements:" "${PHASE_DIR}"/*-PLAN.md 2>/dev/null | tr -d '[]' | tr ',' '\n' | sed 's/^[[:space:]]*//' | grep -oE "SDK-READ-0[1-4]" | sort -u)
for id in SDK-READ-01 SDK-READ-02 SDK-READ-03 SDK-READ-04; do
  if echo "$PLAN_REQS" | grep -q "$id"; then echo "  ✓ $id covered"; else echo "  ✗ $id UNCOVERED"; fi
done

echo ""
echo "===§13a DECISION COVERAGE GATE (blocking)==="
GATE_RESULT=$(gsd_run query check.decision-coverage-plan "${PHASE_DIR}" "${CONTEXT_PATH}" 2>/dev/null)
echo "$GATE_RESULT" | node -e "
const raw=require('fs').readFileSync(0,'utf8');
try { const o=JSON.parse(raw); const d=o.data||o;
  console.log('passed:', d.passed, '| skipped:', d.skipped, '| covered:', d.covered, '/', d.total);
  if (d.uncovered && d.uncovered.length) { console.log('UNCOVERED:'); for (const u of d.uncovered) console.log('  -', u.id, '|', u.category, '|', (u.text||'').slice(0,80)); }
  if (d.message && !(d.passed)) console.log('MESSAGE:', d.message);
} catch(e){ console.log('raw:', raw.slice(0,500)); }
"
